  <main class="app">
    <h1>할일 관리</h1>

    <form id="todo-form">
      <input id="new-todo" type="text" placeholder="할일을 입력하세요" autocomplete="off" maxlength="200" />
      <button type="submit" class="add-btn">추가</button>
