  <script>
    const STORAGE_KEY = "simple-todos";

    const form = document.getElementById("todo-form");
    const input = document.getElementById("new-todo");
    const list = document.getElementById("todo-list");
    const emptyMsg = document.getElementById("empty");
    const countEl = document.getElementById("count");
    const filterButtons = document.querySelectorAll(".filters button");

    let todos = load();
    let currentFilter = "all";

    function load() {
      try {
        const data = JSON.parse(localStorage.getItem(STORAGE_KEY));
        return Array.isArray(data) ? data : [];
      } catch {
        return []; // 저장값이 손상된 경우 빈 목록으로 시작
      }
    }

    function save() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    }

    function addTodo(text) {
      todos.push({ id: Date.now().toString(36) + Math.random().toString(36).slice(2), text, done: false });
      save();
      render();
    }

    function toggleTodo(id) {
      const todo = todos.find(t => t.id === id);
      if (todo) {
        todo.done = !todo.done;
        save();
        render();
      }
    }

    function deleteTodo(id) {
      todos = todos.filter(t => t.id !== id);
      save();
      render();
    }

    function visibleTodos() {
      if (currentFilter === "active") return todos.filter(t => !t.done);
      if (currentFilter === "completed") return todos.filter(t => t.done);
      return todos;
    }

    function render() {
      list.innerHTML = "";
      const items = visibleTodos();

      for (const todo of items) {
        const li = document.createElement("li");
        if (todo.done) li.classList.add("done");

        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.checked = todo.done;
        checkbox.setAttribute("aria-label", "완료 표시");
        checkbox.addEventListener("change", () => toggleTodo(todo.id));

        const span = document.createElement("span");
        span.className = "text";
        span.textContent = todo.text; // textContent로 넣어 HTML 삽입 방지

        const del = document.createElement("button");
        del.type = "button";
        del.className = "delete-btn";
        del.textContent = "삭제";
        del.addEventListener("click", () => deleteTodo(todo.id));

        li.append(checkbox, span, del);
        list.appendChild(li);
      }

      if (items.length === 0) {
        emptyMsg.hidden = false;
        emptyMsg.textContent =
          todos.length === 0 ? "할일이 없습니다. 위에서 추가해 보세요." :
          currentFilter === "active" ? "진행 중인 할일이 없습니다." :
          "완료된 할일이 없습니다.";
      } else {
        emptyMsg.hidden = true;
      }

      const remaining = todos.filter(t => !t.done).length;
      countEl.textContent = `전체 ${todos.length}개 · 남은 할일 ${remaining}개`;
    }

    form.addEventListener("submit", e => {
      e.preventDefault();
      const text = input.value.trim();
      if (!text) return;
      addTodo(text);
      input.value = "";
      input.focus();
    });

    filterButtons.forEach(btn => {
      btn.addEventListener("click", () => {
        currentFilter = btn.dataset.filter;
        filterButtons.forEach(b => b.classList.toggle("active", b === btn));
        render();
      });
    });

    render();
  </script>
</body>
</html>
