### `unitconv.py`

```python
#!/usr/bin/env python3
"""단위 변환기 MVP: 길이·무게·온도."""
import argparse
import sys

# 기준 단위(m, kg)에 대한 배율. 국제 정의값 사용.
LINEAR = {
    "length": {
        "mm": 0.001, "cm": 0.01, "m": 1.0, "km": 1000.0,
        "in": 0.0254, "ft": 0.3048, "yd": 0.9144, "mi": 1609.344,
    },
    "mass": {
        "mg": 1e-6, "g": 0.001, "kg": 1.0,
        "oz": 0.028349523125, "lb": 0.45359237,
    },
}
TEMPERATURE = {"C", "F", "K"}


class ConversionError(ValueError):
    pass


def category_of(unit: str) -> str:
    for cat, table in LINEAR.items():
        if unit in table:
            return cat
    if unit in TEMPERATURE:
        return "temperature"
    raise ConversionError(f"지원하지 않는 단위: {unit!r}")


def _to_kelvin(v: float, u: str) -> float:
    if u == "K":
        return v
    if u == "C":
        return v + 273.15
    return (v - 32) * 5 / 9 + 273.15  # F


def _from_kelvin(k: float, u: str) -> float:
    if u == "K":
        return k
    if u == "C":
        return k - 273.15
    return (k - 273.15) * 9 / 5 + 32  # F


def convert(value: float, src: str, dst: str) -> float:
    c_src, c_dst = category_of(src), category_of(dst)
    if c_src != c_dst:
        raise ConversionError(f"범주가 다름: {src}({c_src}) → {dst}({c_dst})")
    if c_src == "temperature":
        k = _to_kelvin(value, src)
        if k < 0:
            raise ConversionError("절대영도(0 K) 미만 온도는 허용되지 않음")
        return _from_kelvin(k, dst)
    table = LINEAR[c_src]
    return value * table[src] / table[dst]


def all_units():
    return {**{c: list(t) for c, t in LINEAR.items()},
            "temperature": sorted(TEMPERATURE)}


def main(argv=None) -> int:
    p = argparse.ArgumentParser(description="단위 변환기 (길이·무게·온도)")
    p.add_argument("value", nargs="?", type=float, help="변환할 값")
    p.add_argument("src", nargs="?", help="원래 단위 (예: cm)")
    p.add_argument("dst", nargs="?", help="목표 단위 (예: in)")
    p.add_argument("--list", action="store_true", help="지원 단위 목록")
    p.add_argument("-p", "--precision", type=int, default=6, help="소수 자릿수")
    a = p.parse_args(argv)

    if a.list:
        for cat, units in all_units().items():
            print(f"{cat}: {', '.join(units)}")
        return 0
    if None in (a.value, a.src, a.dst):
        p.error("값, 원래 단위, 목표 단위가 모두 필요함 (예: 10 cm in)")
    try:
        r = convert(a.value, a.src, a.dst)
    except ConversionError as e:
        print(f"오류: {e}", file=sys.stderr)
        return 1
    print(f"{a.value:g} {a.src} = {r:.{a.precision}g} {a.dst}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

### `test_unitconv.py`

```python
import itertools
import math
import unittest

from unitconv import ConversionError, all_units, convert

REL = 1e-9


class TestConvert(unittest.TestCase):
    def test_known_values(self):
        cases = [
            (1, "in", "cm", 2.54), (1, "mi", "km", 1.609344),
            (1, "ft", "in", 12), (1, "yd", "ft", 3),
            (1, "lb", "kg", 0.45359237), (16, "oz", "lb", 1),
            (1, "kg", "g", 1000), (100, "C", "F", 212),
            (32, "F", "C", 0), (0, "K", "C", -273.15),
            (-40, "C", "F", -40),
        ]
        for v, s, d, expected in cases:
            with self.subTest(f"{v} {s}->{d}"):
                self.assertTrue(math.isclose(convert(v, s, d), expected,
                                             rel_tol=REL, abs_tol=1e-9))

    def test_all_pairs_roundtrip(self):
        for cat, units in all_units().items():
            v = 300.0 if cat == "temperature" else 123.456
            for s, d in itertools.product(units, repeat=2):
                with self.subTest(f"{s}<->{d}"):
                    back = convert(convert(v, s, d), d, s)
                    self.assertTrue(math.isclose(back, v, rel_tol=REL))

    def test_cross_category_rejected(self):
        with self.assertRaises(ConversionError):
            convert(1, "m", "kg")

    def test_unknown_unit(self):
        with self.assertRaises(ConversionError):
            convert(1, "parsec", "m")

    def test_below_absolute_zero(self):
        with self.assertRaises(ConversionError):
            convert(-300, "C", "K")


if __name__ == "__main__":
    unittest.main()
```

