### 동작 요약
- **범주 탭**: 길이 · 무게 · 온도 · 부피
- **양방향 입력**: 위·아래 어느 칸에 입력해도 반대쪽 칸이 즉시 계산됩니다.
- **⇅ 버튼**: 두 단위를 맞바꿉니다.
- **온도**: 비례 관계가 아니어서 섭씨를 기준으로 변환 함수를 따로 씁니다 (°C/°F/K).
- **표시값**: 유효숫자 10자리로 반올림해 `0.30000000000000004` 같은 부동소수점 오차가 보이지 않게 했습니다.

범주나 단위를 늘리려면 `CATEGORIES`에 항목만 추가하면 됩니다. 비례 단위는 `[이름, 기준 단위 대비 배수]`, 비례가 아닌 단위는 `toBase`/`fromBase` 함수를 넣으면 됩니다.

**해석**: 금액 계산용 유틸리티 모듈(파싱·사칙연산·반올림·분배·부가세·포맷)을 새로 작성
**보강**: MVP는 정수 최소단위(bigint) 기반 Money 타입, 가감·배율·퍼센트, 반올림 모드, 잔액 손실 없는 분배, 부가세 분리, 단위 절사, 통화 포맷까지 / 환율 변환·DB 연동은 제외 [가정: 기존 코드 맥락이 없어 TypeScript, KRW 우선(USD·JPY·EUR 포함), 부동소수점 오차를 피하려고 bigint 사용]

```ts
// money.ts
// 모든 금액은 통화의 최소 단위(KRW: 원, USD: 센트) bigint 정수로 보관한다.

export type Currency = 'KRW' | 'JPY' | 'USD' | 'EUR';
export type Rounding = 'halfUp' | 'halfEven' | 'floor' | 'ceil' | 'trunc';

const DECIMALS: Record<Currency, number> = { KRW: 0, JPY: 0, USD: 2, EUR: 2 };

export interface Money {
  readonly amount: bigint; // 최소 단위
  readonly currency: Currency;
}

// ---------- 내부 헬퍼 ----------

const abs = (n: bigint) => (n < 0n ? -n : n);
const pow10 = (n: number) => 10n ** BigInt(n);

/** "1,234.56" → { int: 123456n, scale: 2 } (float를 거치지 않음) */
function parseDecimal(input: string | number): { int: bigint; scale: number } {
  if (typeof input === 'number' && !Number.isFinite(input)) {
    throw new RangeError(`유효하지 않은 숫자: ${input}`);
  }
  const s = String(input).replace(/,/g, '').trim();
  const m = /^([+-])?(\d+)(?:\.(\d+))?$/.exec(s);
  if (!m) throw new RangeError(`숫자 형식이 아님: "${input}"`);
  const [, sign, whole, frac = ''] = m;
  const int = BigInt(whole + frac) * (sign === '-' ? -1n : 1n);
  return { int, scale: frac.length };
}

/** n / d 를 지정한 방식으로 반올림한 정수 */
function divRound(n: bigint, d: bigint, mode: Rounding): bigint {
  if (d === 0n) throw new RangeError('0으로 나눌 수 없음');
  if (d < 0n) { n = -n; d = -d; }
  const q = n / d;          // 0 방향 절사
  const r = n % d;
  if (r === 0n) return q;
  const sign = n < 0n ? -1n : 1n;
  const twice = abs(r) * 2n;
  switch (mode) {
    case 'trunc':    return q;
    case 'floor':    return sign < 0n ? q - 1n : q;
    case 'ceil':     return sign > 0n ? q + 1n : q;
    case 'halfUp':   return twice >= d ? q + sign : q;           // 0에서 멀어지는 방향
    case 'halfEven':
      if (twice !== d) return twice > d ? q + sign : q;
      return q % 2n === 0n ? q : q + sign;                     // 은행가 반올림
  }
}

function assertSameCurrency(a: Money, b: Money) {
  if (a.currency !== b.currency) {
    throw new TypeError(`통화 불일치: ${a.currency} vs ${b.currency}`);
  }
}

// ---------- 생성 / 변환 ----------

/** 표시 단위 값으로 생성. money('12.34', 'USD') → 1234센트. 소수 자릿수 초과 시 에러 */
export function money(value: string | number, currency: Currency): Money {
  const { int, scale } = parseDecimal(value);
  const d = DECIMALS[currency];
  if (scale > d) {
    throw new RangeError(`${currency}는 소수 ${d}자리까지만 허용: ${value}`);
  }
  return { amount: int * pow10(d - scale), currency };
}

/** 최소 단위 정수로 생성 */
export function fromMinor(amount: bigint | number, currency: Currency): Money {
  if (typeof amount === 'number' && !Number.isSafeInteger(amount)) {
    throw new RangeError(`최소 단위는 안전한 정수여야 함: ${amount}`);
  }
  return { amount: BigInt(amount), currency };
}

/** 1234n USD → "12.34" (정밀도 손실 없음) */
export function toDecimalString(m: Money): string {
  const d = DECIMALS[m.currency];
  const neg = m.amount < 0n;
  const digits = abs(m.amount).toString().padStart(d + 1, '0');
  const body = d === 0 ? digits : `${digits.slice(0, -d)}.${digits.slice(-d)}`;
  return (neg ? '-' : '') + body;
}

/** 통화 형식 문자열. format(money('15000','KRW')) → "₩15,000" */
export function format(m: Money, locale = 'ko-KR'): string {
  const nf = new Intl.NumberFormat(locale, { style: 'currency', currency: m.currency });
  // 문자열 입력으로 큰 금액도 정밀도 유지 (Node 20+, 최신 브라우저)
  return nf.format(toDecimalString(m) as unknown as number);
}

// ---------- 연산 ----------

export const add = (a: Money, b: Money): Money => {
  assertSameCurrency(a, b);
  return { amount: a.amount + b.amount, currency: a.currency };
};

export const subtract = (a: Money, b: Money): Money => {
  assertSameCurrency(a, b);
  return { amount: a.amount - b.amount, currency: a.currency };
};

export const sum = (items: Money[], currency: Currency): Money =>
  items.reduce((acc, m) => add(acc, m), fromMinor(0n, currency));

export const compare = (a: Money, b: Money): -1 | 0 | 1 => {
  assertSameCurrency(a, b);
  return a.amount < b.amount ? -1 : a.amount > b.amount ? 1 : 0;
};

/** 배율 곱. factor는 문자열 권장: multiply(m, '1.15') */
export function multiply(m: Money, factor: string | number, rounding: Rounding = 'halfUp'): Money {
  const { int, scale } = parseDecimal(factor);
  return { amount: divRound(m.amount * int, pow10(scale), rounding), currency: m.currency };
}

/** 퍼센트 금액. percent(m, 3.5) → m의 3.5% */
export function percent(m: Money, pct: string | number, rounding: Rounding = 'halfUp'): Money {
  const { int, scale } = parseDecimal(pct);
  return { amount: divRound(m.amount * int, pow10(scale) * 100n, rounding), currency: m.currency };
}

/**
 * 비율대로 분배. 합계가 항상 원금과 정확히 일치한다(남는 최소 단위는 앞에서부터 1씩).
 * allocate(money('10000','KRW'), [1,1,1]) → [3334, 3333, 3333]
 */
export function allocate(m: Money, ratios: number[]): Money[] {
  if (ratios.length === 0) throw new RangeError('ratios가 비어 있음');
  if (ratios.some(r => !Number.isSafeInteger(r) || r < 0)) {
    throw new RangeError('ratios는 0 이상의 정수여야 함');
  }
  const weights = ratios.map(BigInt);
  const total = weights.reduce((a, b) => a + b, 0n);
  if (total === 0n) throw new RangeError('ratios 합이 0');

  const sign = m.amount < 0n ? -1n : 1n;
  const base = abs(m.amount);
  const shares = weights.map(w => (base * w) / total);
  let remainder = base - shares.reduce((a, b) => a + b, 0n);
  for (let i = 0; remainder > 0n; i = (i + 1) % shares.length) {
    if (weights[i] === 0n) continue;
    shares[i] += 1n;
    remainder -= 1n;
  }
  return shares.map(s => ({ amount: s * sign, currency: m.currency }));
}

/** n등분 (더치페이 등) */
export const split = (m: Money, n: number): Money[] => allocate(m, Array(n).fill(1));

/**
 * 부가세 포함 금액 → 공급가액 + 부가세.
 * 공급가액 = 합계 × 100 / (100 + 세율), 부가세 = 합계 − 공급가액 (합이 항상 일치)
 */
export function splitVat(
  total: Money,
  ratePct: string | number = 10,
  rounding: Rounding = 'halfUp',
): { supply: Money; vat: Money } {
  const { int, scale } = parseDecimal(ratePct);
  const hundred = 100n * pow10(scale);
  const supply = divRound(total.amount * hundred, hundred + int, rounding);
  return {
    supply: { amount: supply, currency: total.currency },
    vat: { amount: total.amount - supply, currency: total.currency },
  };
}

/** 단위 맞춤. roundToUnit(m, 10) → 10원 단위 절사(기본 trunc) */
export function roundToUnit(m: Money, unit: number, rounding: Rounding = 'trunc'): Money {
  if (!Number.isSafeInteger(unit) || unit <= 0) throw new RangeError('unit은 양의 정수(최소 단위)');
  const u = BigInt(unit);
  return { amount: divRound(m.amount, u, rounding) * u, currency: m.currency };
}
```

사용 예:

```ts
const price = money('19,900', 'KRW');
format(multiply(price, 3));                 // "₩59,700"
format(percent(price, 15));                 // "₩2,985"
split(money('10000', 'KRW'), 3).map(toDecimalString);   // ["3334","3333","3333"]
splitVat(money('11000', 'KRW'));            // supply 10000, vat 1000
roundToUnit(money('12345', 'KRW'), 100);    // 12300 (100원 단위 절사)

const usd = money('0.10', 'USD');
toDecimalString(add(usd, money('0.20', 'USD')));         // "0.30" (0.1+0.2 오차 없음)
multiply(money('1.00', 'USD'), '1.005', 'halfEven');     // 100센트
```

설계 포인트:
- **float 미사용**: 입력은 문자열로 받아 bigint로 파싱하므로 `0.1 + 0.2` 같은 오차가 없습니다. `number`를 넣어도 되지만 계산값보다는 리터럴에만 쓰는 걸 권장합니다.
- **반올림은 항상 명시 가능**: 기본은 `halfUp`(사사오입), 분배·부가세는 합계가 원금과 정확히 맞도록 나머지를 보정합니다.
- **부가세 원 미만 처리**: [가정: 공급가액을 사사오입하고 부가세는 차액으로 계산] — 업무 기준이 "부가세 절사"라면 `splitVat(total, 10, 'ceil')`로 공급가액을 올리면 됩니다.
- 언어·프레임워크가 다르거나(예: Python, Kotlin) 특정 통화만 필요하면 말씀해 주세요.
